-- Meeoww database schema (PostgreSQL)
CREATE TABLE users (id SERIAL PRIMARY KEY, display_name VARCHAR(80) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT, avatar_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE songs (id SERIAL PRIMARY KEY, title VARCHAR(180) NOT NULL, artist VARCHAR(180) NOT NULL, album VARCHAR(180), genre VARCHAR(80), cover_url TEXT, audio_url TEXT, duration_seconds INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE playlists (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE playlist_songs (playlist_id INTEGER NOT NULL REFERENCES playlists(id) ON DELETE CASCADE, song_id INTEGER NOT NULL REFERENCES songs(id) ON DELETE CASCADE, position INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (playlist_id, song_id));
CREATE TABLE listening_history (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, song_id INTEGER NOT NULL REFERENCES songs(id) ON DELETE CASCADE, listened_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
